layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: background-color 0.3s, color 0.3s, border-color 0.3s }
article[data-ryt="rec-card"] { background-color: color-mix(in srgb, var(--ryt-bg) 90%, transparent); border-top: 1px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); border-left: 1px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); border-radius: 16px; box-shadow: rgba(255, 126, 80, 0.15) 0px 8px 32px 0px; transition: opacity 0.5s, transform 0.5s; position: relative }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.3s, color 0.3s, border-color 0.3s }
[data-ryt="brand"] { color: var(--ryt-accent); background-image: linear-gradient(135deg, var(--ryt-border) 0%, rgb(255, 127, 80) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: SFMono-Regular, Consolas, "Liberation Mono", monospace; font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.3s, color 0.3s, border-color 0.3s; background-clip: text; -webkit-text-fill-color: rgba(0, 0, 0, 0); -webkit-background-clip: text; -webkit-text-fill-color: transparent }
[data-ryt="header"] { border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); box-shadow: rgba(255, 126, 80, 0.15) 0px 4px 20px 0px; border-top: none }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 20px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: 0.3s }
[data-ryt="button"] { color: rgb(90, 75, 124); background-color: color-mix(in srgb, var(--ryt-bg) 90%, transparent); border-top: 2px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); border-right: 2px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); border-bottom: 2px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); border-left: 2px solid color-mix(in srgb, var(--ryt-border) 20%, transparent); border-radius: 50%; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(90, 75, 124); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.3s }
[data-ryt="review"] { color: rgb(90, 75, 124); font-family: var(--ryt-font-heading); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(90, 75, 124); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.3s, color 0.3s, border-color 0.3s }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: SFMono-Regular, Consolas, "Liberation Mono", monospace; font-size: 12.8px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.3s, color 0.3s, border-color 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s }
body { background-image: linear-gradient(135deg, rgb(255, 229, 180) 0%, rgb(255, 204, 203) 25%, rgb(221, 160, 221) 75%, rgb(152, 216, 232) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.2px; font-weight: 600; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.3s, color 0.3s, border-color 0.3s }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-shadow: 0 0 20px color-mix(in srgb, var(--ryt-border) 30%, transparent) }
[data-ryt="button"]:hover { color: white; transform: scale(1.1); box-shadow: 0 4px 15px color-mix(in srgb, var(--ryt-border) 30%, transparent) }
[data-ryt="nav"] a:hover { box-shadow: 0 4px 15px color-mix(in srgb, var(--ryt-border) 30%, transparent) }
[data-ryt="brand"]::before { content: "☕"; display: block; width: 23.9688px; height: 23.0312px; color: rgb(255, 127, 80); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: SFMono-Regular, Consolas, "Liberation Mono", monospace; font-size: 19.2px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 127, 80); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; filter: drop-shadow(rgb(255, 127, 80) 0px 0px 8px); transition: all; -webkit-text-fill-color: rgb(255, 127, 80) }
article[data-ryt="rec-card"]::before { content: ""; display: block; position: absolute; width: 4px; height: 295.484px; color: var(--ryt-text); background-image: linear-gradient(135deg, var(--ryt-border) 0%, rgb(255, 127, 80) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text); top: 0px; left: 0px }
article[data-ryt="rec-card"]:hover { transform: translateX(8px) translateY(-2px) }
